export const BINDING_SECTIONS = {target:'TARGET',actor:'ACTOR',roles:'ROLES',memberships:'MEMBERSHIPS',functions:'FUNCTIONS',tableHooks:'TABLE_HOOKS',history:'HISTORY'};
