  if(!r.caPath||!fs.existsSync(r.caPath))return fail('ROOT_CERT_MISSING');
  if(sha(fs.readFileSync(r.caPath))!==OFFICIAL_CA_SHA256)return fail('CA_HASH_MISMATCH');
